function fresh(p, tick) {
  return p.kind === 'bucket' ? { num: p.capacity * p.per, last: tick } : { ticks: [] }
}

function advance(p, s, tick) {
  if (p.kind === 'bucket') {
    s.num += p.refill * (tick - s.last)
    const max = p.capacity * p.per
    if (s.num > max) s.num = max
    s.last = tick
  } else {
    const cut = tick - p.span
    s.ticks = s.ticks.filter((t) => t > cut)
  }
}

function allows(p, s) {
  return p.kind === 'bucket' ? s.num >= p.per : BigInt(s.ticks.length) < p.limit
}

function record(p, s, tick) {
  if (p.kind === 'bucket') s.num -= p.per
  else s.ticks.push(tick)
}

export function simulate({ routes, events }) {
  const states = new Map()
  const results = []
  for (const { tick, key } of events) {
    let best = null
    for (const prefix of routes.keys()) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
    }
    let denier = null
    if (best !== null) {
      const list = routes.get(best)
      const ss = list.map((p) => {
        const id = p.name + '\0' + key
        if (!states.has(id)) states.set(id, fresh(p, tick))
        const s = states.get(id)
        advance(p, s, tick)
        return s
      })
      for (let i = 0; i < list.length; i++) {
        if (!allows(list[i], ss[i])) { denier = list[i].name; break }
      }
      if (denier === null) list.forEach((p, i) => record(p, ss[i], tick))
    }
    results.push({ tick: String(tick), key, denier })
  }
  return results
}
