 * verdicts per key.
 */
import { readFileSync } from 'node:fs'
import { parse, ParseError } from './parse.js'
import { simulate } from './sim.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

let program
try {
  program = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write(`error: line ${e.line}: ${e.message}\n`)
  process.exit(2)
}

const results = simulate(program)
let out = ''
if (mode === 'replay') {
  for (const r of results) out += `${r.tick} ${r.key} ${r.denier === null ? 'allow' : 'deny ' + r.denier}\n`
} else {
  const per = new Map()
  let a = 0
  let d = 0
  for (const r of results) {
    const s = per.get(r.key) ?? { a: 0, d: 0 }
    if (r.denier === null) { s.a++; a++ } else { s.d++; d++ }
    per.set(r.key, s)
  }
  for (const key of [...per.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
    out += `${key} allowed=${per.get(key).a} denied=${per.get(key).d}\n`
  }
  out += `total allowed=${a} denied=${d}\n`
}
process.stdout.write(out)
